import calendar
import csv
import json
import re
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP


DATASET_DIR = "/app/dataset"


def _read_csv(path: str) -> list[dict[str, str]]:
    with open(path, newline="") as f:
        return list(csv.DictReader(f))


def _pesel_is_valid(value: str) -> bool:
    if len(value) != 11 or not value.isdigit():
        return False
    weights = (1, 3, 7, 9, 1, 3, 7, 9, 1, 3)
    checksum = sum(int(value[i]) * weights[i] for i in range(10))
    return (10 - checksum % 10) % 10 == int(value[-1])


def _hamming_distance(left: str, right: str) -> int:
    if len(left) != len(right):
        return 10**9
    return sum(a != b for a, b in zip(left, right))


def _build_employee_mapper(employee_ids: set[str]):
    def mapper(employee_id: str) -> str | None:
        if employee_id in employee_ids:
            return employee_id
        if _pesel_is_valid(employee_id):
            return None

        candidates = sorted(
            (_hamming_distance(employee_id, valid_id), valid_id)
            for valid_id in employee_ids
        )
        if not candidates:
            return None
        best_distance, best_id = candidates[0]
        if best_distance <= 3 and (
            len(candidates) == 1 or candidates[1][0] > best_distance
        ):
            return best_id
        return None

    return mapper


def _parse_task_ids(value: str) -> tuple[int, ...]:
    return tuple(int(match) for match in re.findall(r"\d+", value or ""))


def _parse_clamped_date(value: str) -> date | None:
    try:
        year_text, month_text, day_text = value.split("-")
        year = int(year_text)
        month = int(month_text)
        day = int(day_text)
    except ValueError:
        return None

    if month < 1 or month > 12:
        return None
    last_day = calendar.monthrange(year, month)[1]
    return date(year, month, min(max(day, 1), last_day))


def _first_weekday_in_month(year: int, month: int, weekday: int) -> date:
    first = date(year, month, 1)
    return first + timedelta(days=(weekday - first.weekday()) % 7)


def _previous_month(year: int, month: int) -> tuple[int, int]:
    if month == 1:
        return year - 1, 12
    return year, month - 1


def _billing_month(work_date: date, billing_weekday: int) -> tuple[int, int]:
    month_start = _first_weekday_in_month(
        work_date.year, work_date.month, billing_weekday
    )
    if work_date < month_start:
        return _previous_month(work_date.year, work_date.month)
    return work_date.year, work_date.month


def _round_salary(value: Decimal) -> int:
    return int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def answer() -> dict[str, list[int]]:
    employees = _read_csv(f"{DATASET_DIR}/employees.csv")
    tasks = _read_csv(f"{DATASET_DIR}/tasks.csv")
    timesheet = _read_csv(f"{DATASET_DIR}/timesheet.csv")

    hourly_rates = {
        row["PESEL"]: Decimal(row["hourly_rate"])
        for row in employees
        if _pesel_is_valid(row["PESEL"])
    }
    employee_ids = set(hourly_rates)
    map_employee_id = _build_employee_mapper(employee_ids)

    task_pay = {
        int(row["task_id"]): Decimal(row["pay_per_completion"])
        for row in tasks
        if row["task_id"].isdigit()
    }

    dated_rows: list[tuple[dict[str, str], date]] = []
    for row in timesheet:
        work_date = _parse_clamped_date(row["date"])
        if work_date is not None:
            dated_rows.append((row, work_date))

    if not dated_rows:
        return {pesel: [] for pesel in sorted(employee_ids)}

    billing_weekday = min(work_date for _, work_date in dated_rows).weekday()

    totals: dict[str, defaultdict[tuple[int, int], Decimal]] = {
        pesel: defaultdict(Decimal) for pesel in employee_ids
    }
    billing_months: set[tuple[int, int]] = set()
    seen_rows: set[tuple[object, ...]] = set()

    for row, work_date in dated_rows:
        pesel = map_employee_id(row["employee_id"])
        if pesel is None:
            continue

        try:
            hours = Decimal(row["hours_worked"])
        except Exception:
            continue
        if hours < 0:
            continue

        task_ids = _parse_task_ids(row["performed_tasks"])
        normalized_key = (
            work_date.isoformat(),
            pesel,
            hours,
            task_ids,
            row.get("facility_id", ""),
            row.get("salary_amount", ""),
            row.get("bonus", ""),
        )
        if normalized_key in seen_rows:
            continue
        seen_rows.add(normalized_key)

        month = _billing_month(work_date, billing_weekday)
        billing_months.add(month)

        valid_bonus = sum(
            (task_pay[task_id] for task_id in task_ids if task_id in task_pay),
            Decimal(0),
        )
        totals[pesel][month] += hours * hourly_rates[pesel] + valid_bonus

    sorted_months = sorted(billing_months)
    return {
        pesel: [_round_salary(totals[pesel][month]) for month in sorted_months]
        for pesel in sorted(employee_ids)
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
